mapper.select:
SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM view_log 
WHERE user_id = #{userId} 
  AND content_id = #{contentId}

mapper.update:
UPDATE contents
SET views = views + 1
WHERE content_id = #{contentId}

mapper.insert:
INSERT into favorites (
    user_id,
    content_id
) VALUES (
    #{userId},
    #{contentId}
)

mapper.delete:
DELETE 
FROM favorites
WHERE user_id = #{userId} 
  and content_id = #{contentId}
